    public static IHtmlContent Svg(string name, int size = 20, string? cssClass = null)
    {
        if (!Paths.TryGetValue(name, out var inner))
        {
            inner = Paths["info"];
        }

        var css = string.IsNullOrEmpty(cssClass) ? "icon" : "icon " + cssClass;
        return new HtmlString(
            $"<svg class=\"{css}\" width=\"{size}\" height=\"{size}\" viewBox=\"0 0 24 24\" fill=\"none\" " +
            "stroke=\"currentColor\" stroke-width=\"1.9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">" +
            inner + "</svg>");
    }

    public static bool Has(string name) => Paths.ContainsKey(name);
